// При создании задачи скопировать набор параметров её Типа операции
// в дочернюю таблицу «Значения параметров задачи» и привязать к задаче.
const NC = $env.NOCODB_INTERNAL_URL;
const BASE = $env.NC_BASE_ID;
const TOKEN = $env.NC_TOKEN;
const H = { 'xc-token': TOKEN };
const data = (t) => `${NC}/api/v1/db/data/noco/${BASE}/${encodeURIComponent(t)}`;

async function list(t) { const r = await this.helpers.httpRequest({ method: 'GET', url: data(t) + '?limit=1000', headers: H, json: true }); return r.list || []; }
async function create(t, body) { return this.helpers.httpRequest({ method: 'POST', url: data(t), headers: H, body, json: true }); }
function linkId(v) { if (!v) return null; if (Array.isArray(v)) return v[0]?.Id ?? v[0]?.id ?? null; return v.Id ?? v.id ?? null; }

// найти id link-колонки «Значения параметров» на таблице «Задачи на участки» через meta
async function paramLinkColumnId() {
  const bases = await this.helpers.httpRequest({ method: 'GET', url: `${NC}/api/v1/db/meta/projects/${BASE}/tables`, headers: H, json: true });
  const tbl = (bases.list || []).find((t) => t.title === 'Задачи на участки');
  const full = await this.helpers.httpRequest({ method: 'GET', url: `${NC}/api/v1/db/meta/tables/${tbl.id}`, headers: H, json: true });
  const col = full.columns.find((c) => c.title === 'Значения параметров');
  return col?.id;
}
async function link(taskId, colId, childId) {
  return this.helpers.httpRequest({ method: 'POST', url: `${data('Задачи на участки')}/${taskId}/mm/${colId}/${childId}`, headers: H, json: true });
}

const body = $input.first().json.body || $input.first().json;
const rows = body?.data?.rows || (body?.data ? [body.data] : []);
const rec = rows[0] || {};
const taskId = rec.Id ?? rec.id;
const opTypeId = linkId(rec['Типы операций']);
if (!taskId || !opTypeId) return [{ json: { skipped: true, reason: 'нет задачи или типа операции' } }];

const params = await list.call(this, 'Параметры типов');
const mine = params.filter((p) => linkId(p['Типы операций']) === opTypeId);
const colId = await paramLinkColumnId.call(this);

const created = [];
for (const p of mine) {
  const row = await create.call(this, 'Значения параметров задачи', {
    'Параметр': p['Параметр'], 'Единица': p['Единица'], 'Обязательный': p['Обязательный'], 'Значение': ''
  });
  const childId = row.Id ?? row.id;
  if (colId) await link.call(this, taskId, colId, childId);
  created.push(p['Параметр']);
}
return [{ json: { taskId, opTypeId, created } }];
